const express = require('express');
const app = express();

app.put('/api/updateData', (req, res) => {
  // Burada PUT isteğini işle
  // Gerekli verileri al ve güncelleme işlemini yap
  // Sonucu istemciye geri döndür

  res.json({ message: 'Veri güncellendi' });
});

app.listen(3000, () => {
  console.log('Sunucu çalışıyor...');
});
